import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { toggleStyles } from './toggle.styles.js';

export type ToggleVariant = 'default' | 'outline';
export type ToggleSize = 'sm' | 'md' | 'lg';

/**
 * A pressable toggle button with `aria-pressed`.
 *
 * @element bl-toggle
 * @slot - Toggle button content.
 * @csspart button - The native `<button>` element.
 * @fires bl-change - Emitted when the pressed state changes.
 */
@customElement('bl-toggle')
export class BlToggle extends LitElement {
  static override styles = [tokens, toggleStyles];

  /** Whether the toggle is pressed. */
  @property({ type: Boolean, reflect: true })
  pressed = false;

  /** Whether the toggle is disabled. */
  @property({ type: Boolean })
  disabled = false;

  /** Visual variant. */
  @property({ reflect: true })
  variant: ToggleVariant = 'default';

  /** Size of the toggle. */
  @property({ reflect: true })
  size: ToggleSize = 'md';

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('pressed')) {
      if (this.pressed) {
        this.setAttribute('data-pressed', '');
      } else {
        this.removeAttribute('data-pressed');
      }
    }
    if (changed.has('disabled')) {
      this.setAttribute('aria-disabled', String(this.disabled));
    }
  }

  private _handleClick(): void {
    if (this.disabled) return;
    this.pressed = !this.pressed;
    this.dispatchEvent(
      new CustomEvent('bl-change', {
        detail: { pressed: this.pressed },
        composed: true,
        bubbles: true,
      }),
    );
  }

  private _handleKeyDown(e: KeyboardEvent): void {
    if (this.disabled) return;
    if (e.key === ' ' || e.key === 'Enter') {
      e.preventDefault();
      this._handleClick();
    }
  }

  protected override render() {
    return html`
      <button
        part="button"
        type="button"
        aria-pressed=${this.pressed ? 'true' : 'false'}
        aria-disabled=${this.disabled ? 'true' : 'false'}
        @click=${this._handleClick}
        @keydown=${this._handleKeyDown}
      >
        <slot></slot>
      </button>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-toggle': BlToggle;
  }
}

import { css } from 'lit';

export const toggleStyles = css`
  :host {
    display: inline-block;
  }

  :host([aria-disabled='true']) {
    pointer-events: none;
  }

  button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--bl-spacing-xs);
    border-radius: var(--bl-radius-md);
    font-family: var(--bl-font-family-base);
    font-weight: 500;
    line-height: 1;
    cursor: pointer;
    user-select: none;
    background-color: transparent;
    color: var(--bl-color-neutral-600);
    border: 1px solid var(--bl-color-neutral-300);
    transition:
      background-color var(--bl-transition-fast),
      color var(--bl-transition-fast),
      border-color var(--bl-transition-fast);
  }

  /* Sizes */
  :host([size='sm']) button {
    font-size: var(--bl-font-size-sm);
    padding: var(--bl-spacing-xs) var(--bl-spacing-sm);
    min-height: 1.75rem;
  }

  :host([size='md']) button {
    font-size: var(--bl-font-size-md);
    padding: var(--bl-spacing-sm) var(--bl-spacing-md);
    min-height: 2.25rem;
  }

  :host([size='lg']) button {
    font-size: var(--bl-font-size-lg);
    padding: var(--bl-spacing-sm) var(--bl-spacing-lg);
    min-height: 2.75rem;
  }

  /* Pressed state */
  :host([data-pressed]) button {
    background-color: var(--bl-color-neutral-100);
    color: var(--bl-color-neutral-900);
    border-color: var(--bl-color-neutral-400);
  }

  /* Outline variant */
  :host([variant='outline']) button {
    border-color: var(--bl-color-neutral-300);
  }

  :host([variant='outline'][data-pressed]) button {
    background-color: var(--bl-color-primary-50);
    color: var(--bl-color-primary-700);
    border-color: var(--bl-color-primary-300);
  }

  /* Hover */
  button:hover {
    background-color: var(--bl-color-neutral-100);
  }

  :host([data-pressed]) button:hover {
    background-color: var(--bl-color-neutral-200);
  }

  /* Focus */
  button:focus-visible {
    outline: var(--bl-focus-ring);
    outline-offset: var(--bl-focus-ring-offset);
  }

  /* Disabled */
  :host([aria-disabled='true']) button {
    opacity: 0.5;
    cursor: not-allowed;
  }
`;
